import{c as s,U as r,j as a,g as t,o,a6 as n,n as u}from"./chunks/framework.h4W4t1IS.js";const g=JSON.parse('{"title":"Compte GitHub","description":"","frontmatter":{"title":"Compte GitHub","status":"ready","tags":["env","all"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"env/github.md","filePath":"env/github.md"}'),l={name:"env/github.md"},d={id:"frontmatter-title",tabindex:"-1"};function c(i,e,p,m,b,h){return r(),a("div",null,[t("h1",d,[o(n(i.$frontmatter.title)+" ",1),e[0]||(e[0]=t("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=u('<p>GitHub est une plateforme d&#39;hébergement de dépôts Git en ligne. Elle permet de partager du code, de collaborer en équipe et de garder une copie distante du travail.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Expliquer le rôle de GitHub par rapport à Git</li><li>Créer un compte GitHub avec un nom d&#39;utilisateur professionnel</li><li>Transmettre ton nom d&#39;utilisateur à ton professeur</li></ul></div><h2 id="qu-est-ce-que-github" tabindex="-1">Qu&#39;est-ce que GitHub? <a class="header-anchor" href="#qu-est-ce-que-github" aria-label="Permalink to &quot;Qu&#39;est-ce que GitHub?&quot;">​</a></h2><p>GitHub est un service d&#39;hébergement pour les dépôts Git, propriété de Microsoft. Ce n&#39;est <strong>pas</strong> Git lui-même - Git fonctionne très bien sans GitHub - mais GitHub facilite grandement le partage et la collaboration :</p><ul><li>Héberger une copie distante (<code>origin</code>) de tes dépôts</li><li>Collaborer avec d&#39;autres développeurs (<a href="/420-w30-sf-po2/lexique.html#pull-request" class="lexicon-link" title="Demande d&#39;intégration d&#39;une branche vers une autre sur GitHub, déclenchant un processus de revue de code par les coéquipiers avant la fusion.">pull requests</a>, revues de code)</li><li>Consulter le code d&#39;autres projets (open source)</li><li>Construire un historique public de tes réalisations</li></ul><div class="tip custom-block"><p class="custom-block-title">Une carte de visite</p><p>Ton profil GitHub devient, avec le temps, une vitrine de ton travail : les projets auxquels tu contribues, le code que tu écris, ton nom d&#39;utilisateur. C&#39;est consulté par les recruteurs au même titre que ton profil LinkedIn.</p></div><h2 id="creation-du-compte" tabindex="-1">Création du compte <a class="header-anchor" href="#creation-du-compte" aria-label="Permalink to &quot;Création du compte&quot;">​</a></h2><ol><li>Aller sur <a href="https://github.com" target="_blank" rel="noreferrer">github.com</a></li><li>Cliquer sur <strong>Sign up</strong></li><li>Suivre les étapes (courriel, mot de passe, vérification)</li></ol><div class="warning custom-block"><p class="custom-block-title">Choisis bien ton nom d&#39;utilisateur</p><p>Ton nom d&#39;utilisateur GitHub va te suivre pendant toute ta carrière et apparaîtra dans les projets auxquels tu contribues. Évite les surnoms de jeu vidéo, les blagues ou les suites de chiffres au hasard (ex. <code>xX_ThaBeast_Xx</code>).</p><p>Privilégie un nom <strong>professionnel</strong>, idéalement basé sur ton vrai nom :</p><ul><li><code>prenom-nom</code></li><li><code>prenomnom</code></li><li><code>pnom</code> (initiale du prénom + nom)</li></ul><p>Si le nom est déjà pris, ajoute un chiffre ou des séparateurs (ex: <code>-</code> ou <code>_</code>).</p></div><h2 id="transmission-du-nom-d-utilisateur" tabindex="-1">Transmission du nom d&#39;utilisateur <a class="header-anchor" href="#transmission-du-nom-d-utilisateur" aria-label="Permalink to &quot;Transmission du nom d&#39;utilisateur&quot;">​</a></h2><p>Une fois ton compte créé, envoie un message par <strong>MIO</strong> à ton professeur avec ton nom d&#39;utilisateur GitHub. Cette information est nécessaire pour t&#39;ajouter aux dépôts et équipes du cours.</p>',12))])}const v=s(l,[["render",c]]);export{g as __pageData,v as default};
